  only in target:
    %.inv: %.inv = fcmp oge float %x, 0.000000e+00
    %sel1: %sel1 = select i1 %.inv, float -0.000000e+00, float %x
  only in source:
    %cmp: %cmp = fcmp olt float %x, 0.000000e+00
    %sel: %sel = select nnan nsz i1 %cmp, float %x, float -0.000000e+00

